begin;
create temporary table bakspejl_episode_identity_before on commit drop as select id,source,external_guid,podcast_key from public.podcast_episodes where source='sheet_la_riots_rss' and external_guid in ('11162611001','11162611002','11162611003','11162611004','11162611005','11162611006','11162611007','11162611008','11162611009','11162611010','11162611011','16122471004');
update public.podcast_episodes set podcast_key=case when external_guid between '11162611001' and '11162611004' then 'geniet i lommen' when external_guid between '11162611005' and '11162611008' then 'da aids kom til danmark' when external_guid in ('11162611009','11162611010') then 'manden bag glasset' else 'la riots' end,updated_at=now() where source='sheet_la_riots_rss' and external_guid in ('11162611001','11162611002','11162611003','11162611004','11162611005','11162611006','11162611007','11162611008','11162611009','11162611010','11162611011','16122471004');
update public.podcast_episodes set is_active=false,metadata=coalesce(metadata,'{}'::jsonb)||'{"rateable":false,"exclusion_reason":"dr_promo"}'::jsonb,updated_at=now() where source='sheet_la_riots_rss' and external_guid='16122471004';
do $$ begin if exists(select 1 from bakspejl_episode_identity_before b left join public.podcast_episodes p on p.id=b.id where p.id is null or p.source is distinct from b.source or p.external_guid is distinct from b.external_guid) then raise exception 'Bakspejl migration changed an existing episode identity'; end if; end $$;
commit;
